import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.BvnCBqQl.js";const S=JSON.parse('{"title":"附录 B 术语表","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/b-glossary.md","filePath":"appendix/b-glossary.md","lastUpdated":1791442702000}'),o={name:"appendix/b-glossary.md"};function n(c,t,i,s,l,p){return r(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="附录-b-术语表" tabindex="-1">附录 B 术语表 <a class="header-anchor" href="#附录-b-术语表" aria-label="Permalink to &quot;附录 B 术语表&quot;">​</a></h1><table tabindex="0"><thead><tr><th>术语</th><th>英文</th><th>解释</th><th>章</th></tr></thead><tbody><tr><td>AI 平台</td><td>AIP, AI Platform</td><td>托管 LLM 应用的平台：模型接入、编排、知识库、工具、发布、运营</td><td>0</td></tr><tr><td>应用形态</td><td>App Mode</td><td>completion / chat / agent-chat / workflow / advanced-chat（Chatflow）……</td><td>1</td></tr><tr><td>Chatflow</td><td>advanced-chat</td><td>带会话记忆和 Answer 节点的工作流</td><td>1</td></tr><tr><td>流式输出</td><td>Streaming</td><td>边生成边推送；首字延迟（TTFT）是关键体验指标</td><td>6</td></tr><tr><td>SSE</td><td>Server-Sent Events</td><td>基于 HTTP 的单向事件流，<code>data: ...\\n\\n</code></td><td>6</td></tr><tr><td>Provider</td><td>Model Provider</td><td>模型供应商的适配层，屏蔽各家 API 的差异</td><td>4</td></tr><tr><td>ModelInstance</td><td>—</td><td>“某个租户的某个模型”，凭证已绑定在里面</td><td>4</td></tr><tr><td>Token 预算</td><td>Token Budget</td><td>给历史等可变内容分配的上下文空间</td><td>5</td></tr><tr><td>DSL</td><td>Domain Specific Language</td><td>应用导出的 YAML 文件</td><td>7</td></tr><tr><td>草稿 / 发布</td><td>Draft / Published</td><td>可编辑的版本 vs 线上运行的冻结版本</td><td>7</td></tr><tr><td>乐观锁</td><td>Optimistic Locking</td><td>提交时带上版本号（hash），冲突时拒绝</td><td>7, 15</td></tr><tr><td>选择器</td><td>Selector</td><td>变量地址 <code>[node_id, name, *path]</code>，模板里写作 <code>{{#a.b#}}</code></td><td>8</td></tr><tr><td>变量池</td><td>Variable Pool</td><td>一次运行的共享存储；节点从中读、引擎往里写</td><td>8</td></tr><tr><td>系统变量</td><td>System Variables</td><td><code>sys.query</code>、<code>sys.user_id</code>、<code>sys.conversation_id</code>……</td><td>8</td></tr><tr><td>环境变量</td><td>Environment Variables</td><td>随工作流保存的只读配置，<code>env.*</code></td><td>8</td></tr><tr><td>会话变量</td><td>Conversation Variables</td><td>Chatflow 中跨轮次保存的变量，<code>conversation.*</code></td><td>8</td></tr><tr><td>边状态</td><td>Edge State</td><td>UNKNOWN / TAKEN / SKIPPED</td><td>9</td></tr><tr><td>就绪</td><td>Ready</td><td>入边全部有了结论，并且至少有一条是 TAKEN</td><td>9</td></tr><tr><td>跳过传播</td><td>Skip Propagation</td><td>没被选中的分支一路向下标记为 SKIPPED，直到遇到汇合节点</td><td>9</td></tr><tr><td>执行类型</td><td>Execution Type</td><td>executable / branch / response / container / root</td><td>9</td></tr><tr><td>命令通道</td><td>Command Channel</td><td>外部向引擎发送 Abort 等命令的消息通道</td><td>9, 25</td></tr><tr><td>Layer</td><td>Graph Engine Layer</td><td>观察引擎事件的插件：持久化、执行限制、追踪……</td><td>9, 13</td></tr><tr><td>回复流</td><td>Response Stream</td><td>按 Answer 模板的顺序流式输出各个来源的内容</td><td>10</td></tr><tr><td>容器节点</td><td>Container Node</td><td>内含子图的节点：迭代、循环</td><td>11</td></tr><tr><td>执行帧</td><td>Execution Frame</td><td>graphon 为子图的每一轮创建的独立执行上下文</td><td>11</td></tr><tr><td>错误策略</td><td>Error Strategy</td><td>终止 / 默认值（default-value）/ 异常分支（fail-branch）</td><td>12</td></tr><tr><td>部分成功</td><td>partial-succeeded</td><td>有节点以 exception 状态结束，但整个运行完成了</td><td>12</td></tr><tr><td>人在回路</td><td>HITL, Human In The Loop</td><td>工作流暂停，等人来输入或审批</td><td>12</td></tr><tr><td>单步调试</td><td>Single Step Run</td><td>只运行一个节点，输入由用户提供</td><td>17</td></tr><tr><td>Agent</td><td>—</td><td>由模型决定控制流的“思考 → 调用工具 → 观察”循环</td><td>18</td></tr><tr><td>Function Calling</td><td>Tool Calling</td><td>模型原生返回结构化的工具调用</td><td>18</td></tr><tr><td>ReAct</td><td>Reason + Act</td><td>用提示词约定 Thought / Action / Observation 文本格式</td><td>18</td></tr><tr><td>Scratchpad</td><td>—</td><td>ReAct 中累积的推理记录</td><td>18</td></tr><tr><td>工具提供方</td><td>Tool Provider</td><td>一组共享凭证的工具</td><td>19</td></tr><tr><td>MCP</td><td>Model Context Protocol</td><td>工具接入的开放协议，基于 JSON-RPC 2.0</td><td>20</td></tr><tr><td>Streamable HTTP</td><td>—</td><td>MCP 的 HTTP 传输：POST 发送，响应可以是 JSON 或 SSE</td><td>20</td></tr><tr><td>层组合</td><td>Layer Composition</td><td>agenton 用可组合的层来构建 Agent</td><td>21</td></tr><tr><td>RAG</td><td>Retrieval-Augmented Generation</td><td>先检索、再把检索结果放进提示词生成回答</td><td>22</td></tr><tr><td>分段</td><td>Chunking</td><td>把文档切成适合检索的片段</td><td>22</td></tr><tr><td>重叠</td><td>Chunk Overlap</td><td>相邻分段共享的部分，防止关键信息被切断</td><td>22</td></tr><tr><td>父子分段</td><td>Parent-Child Chunking</td><td>用小块匹配、返回大块</td><td>22</td></tr><tr><td>Embedding</td><td>向量化</td><td>把文本映射成向量，语义相近的文本向量也相近</td><td>22</td></tr><tr><td>BM25</td><td>—</td><td>经典的关键词相关性打分算法</td><td>23</td></tr><tr><td>混合检索</td><td>Hybrid Search</td><td>向量检索 + 全文检索，再融合分数</td><td>23</td></tr><tr><td>Rerank</td><td>重排序</td><td>用 cross-encoder 对候选结果重新打分</td><td>23</td></tr><tr><td>RRF</td><td>Reciprocal Rank Fusion</td><td>基于排名的融合方法</td><td>23</td></tr><tr><td>召回测试</td><td>Hit Testing</td><td>输入问题，查看检索结果和分数</td><td>23</td></tr><tr><td>租户</td><td>Tenant / Workspace</td><td>数据隔离的单位</td><td>24</td></tr><tr><td>RBAC</td><td>Role-Based Access Control</td><td>基于角色的访问控制</td><td>24</td></tr><tr><td>Service API</td><td>—</td><td>面向开发者的 <code>/v1</code> 接口，用 App Key 鉴权</td><td>24</td></tr><tr><td>WebApp</td><td>—</td><td>分享链接背后的公开页面</td><td>24</td></tr><tr><td>事件总线</td><td>Event Bus</td><td>执行端 → API 端的事件通道（Queue / Redis Stream）</td><td>25</td></tr><tr><td>acks_late</td><td>—</td><td>Celery 任务执行完才确认，任务需要幂等</td><td>25</td></tr><tr><td>反向调用</td><td>Backwards Invocation</td><td>插件回调平台的能力（模型、工具……）</td><td>26</td></tr><tr><td>SSRF</td><td>Server-Side Request Forgery</td><td>诱使服务器访问内网资源</td><td>27</td></tr><tr><td>沙箱</td><td>Sandbox</td><td>隔离执行不受信任的代码</td><td>27</td></tr><tr><td>提示词注入</td><td>Prompt Injection</td><td>数据里夹带的指令劫持了模型的行为</td><td>27</td></tr><tr><td>SKIP LOCKED</td><td>—</td><td><code>SELECT ... FOR UPDATE SKIP LOCKED</code>，多个消费者安全地领取任务</td><td>28</td></tr></tbody></table>',2)])])}const P=d(o,[["render",n]]);export{S as __pageData,P as default};
